import { MemoryRouter } from 'react-router-dom'
import type { RepairDetailWithCustomer } from '../../types.js'

// ---------------------------------------------------------------------------
// Mock the hook — must be at top level for hoisting
// ---------------------------------------------------------------------------

const mockUseRepairsForWeek = vi.fn() as ReturnType<typeof vi.fn> & {
  mockReturnValue: (value: unknown) => void
}

vi.mock('../../hooks/useRepairsForWeek.js', () => ({
  useRepairsForWeek: (...args: unknown[]) => mockUseRepairsForWeek(...args),
}))

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function createRepair(id: string, plannedDate: number | null): RepairDetailWithCustomer {
  return {
    id,
    assignedTo: null,
    status: 'in_progress',
    customerNotes: null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate,
    pickupDate: null,
    completedAt: null,
    createdAt: 1706745600000,
    customerName: 'Test Customer',
    bicycleBrand: 'Trek',
    bicycleModel: 'Domane',
    bicycleColor: 'blue',
  }
}

// Feb 2024 week: Mon Feb 5 — Sun Feb 11
const WEEK_MONDAY = 1707033600000 // Feb 5, 2024 00:00 UTC+1 approx
const TUESDAY = 1707120000000     // Feb 6
const WEDNESDAY = 1707206400000   // Feb 7

// ---------------------------------------------------------------------------
// Helper — set up the mock hook return value and render
// ---------------------------------------------------------------------------

function setupHook(repairs: RepairDetailWithCustomer[], isLoading = false) {
  const mockGoPrev = vi.fn()
  const mockGoNext = vi.fn()
  const mockGoToday = vi.fn()

  mockUseRepairsForWeek.mockReturnValue({
    repairs,
    weekStart: WEEK_MONDAY,
    weekEnd: WEEK_MONDAY + 6 * 24 * 60 * 60 * 1000 + 86399999,
    isLoading,
    error: null,
    goPrev: mockGoPrev,
    goNext: mockGoNext,
    goToday: mockGoToday,
  })

  return { mockGoPrev, mockGoNext, mockGoToday }
}

// ---------------------------------------------------------------------------
// Tests: Day columns rendering
// ---------------------------------------------------------------------------

describe('RepairCalendarView — day columns', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    setupHook([])
  })

  it('renders 7 day columns (Mon–Sun)', async () => {
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
    for (const day of days) {
      expect(screen.getByText(day)).toBeInTheDocument()
    }
  })

  it('renders empty columns without placeholder cards', async () => {
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    // Should not find any repair cards when no repairs exist
    expect(screen.queryByText(/Test Customer/)).not.toBeInTheDocument()
  })
})

// ---------------------------------------------------------------------------
// Tests: Week navigation header
// ---------------------------------------------------------------------------

describe('RepairCalendarView — week navigation', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    setupHook([])
  })

  it('renders prev/next/today buttons and week label', async () => {
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    expect(screen.getByRole('button', { name: /previous/i })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /today/i })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /next/i })).toBeInTheDocument()
  })

  it('calls goPrev when prev button is clicked', async () => {
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    const { mockGoPrev } = setupHook([])
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    const prevBtn = screen.getByRole('button', { name: /previous/i })
    fireEvent.click(prevBtn)
    expect(mockGoPrev).toHaveBeenCalled()
  })

  it('calls goNext when next button is clicked', async () => {
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    const { mockGoNext } = setupHook([])
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    const nextBtn = screen.getByRole('button', { name: /next/i })
    fireEvent.click(nextBtn)
    expect(mockGoNext).toHaveBeenCalled()
  })

  it('calls goToday when today button is clicked', async () => {
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    const { mockGoToday } = setupHook([])
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    const todayBtn = screen.getByRole('button', { name: /today/i })
    fireEvent.click(todayBtn)
    expect(mockGoToday).toHaveBeenCalled()
  })
})

// ---------------------------------------------------------------------------
// Tests: Repair distribution into day columns
// ---------------------------------------------------------------------------

describe('RepairCalendarView — repair distribution', () => {
  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('distributes repairs to correct day column by plannedDate', async () => {
    const repairs = [
      createRepair('r1', TUESDAY),   // Feb 6 — Tuesday
      createRepair('r2', WEDNESDAY), // Feb 7 — Wednesday
    ]

    setupHook(repairs)
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )

    // Both repairs should be visible in the calendar
    expect(screen.getAllByText(/Test Customer/)).toHaveLength(2)
  })

  it('uses createdAt as fallback when plannedDate is null', async () => {
    const repair = createRepair('r1', null)

    setupHook([repair])
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )

    expect(screen.getByText(/Test Customer/)).toBeInTheDocument()
  })
})

// ---------------------------------------------------------------------------
// Tests: Loading state
// ---------------------------------------------------------------------------

describe('RepairCalendarView — loading state', () => {
  it('shows loading indicator when isLoading is true', async () => {
    setupHook([], true)
    const { RepairCalendarView } = await import('../RepairCalendarView.js')
    render(
      <MemoryRouter>
        <RepairCalendarView />
      </MemoryRouter>
    )
    expect(screen.getByRole('status')).toBeInTheDocument()
  })
})

/**
 * RepairCard — Component tests.
 *
 * Verifies:
 * - Renders customer name, bicycle model, status badge, assigned worker
 * - Status badge uses STATUS_COLORS mapping
 * - Card body click navigates to repair detail page
 * - Pickup day indicator shown when pickupDate is set
 * - Pickup day indicator hidden when pickupDate is null
 */

import { describe, it, expect } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import { MemoryRouter } from 'react-router-dom'
import type { RepairDetailWithCustomer } from '../../types.js'
import { RepairCard } from '../RepairCard.js'

// ---------------------------------------------------------------------------
// Test fixtures
// ---------------------------------------------------------------------------

function createRepair(overrides?: Partial<RepairDetailWithCustomer>): RepairDetailWithCustomer {
  return {
    id: 'repair-001',
    assignedTo: null,
    status: 'in_progress',
    customerNotes: null,
    internalNotes: null,
    holdReason: null,
    holdReasonNote: null,
    plannedDate: 1706832000000, // Feb 2, 2024
    pickupDate: null,
    completedAt: null,
    createdAt: 1706745600000,
    customerName: 'Jane Doe',
    bicycleBrand: 'Trek',
    bicycleModel: 'Domane SL',
    bicycleColor: 'blue',
    ...overrides,
  }
}

function renderCard(repair?: RepairDetailWithCustomer) {
  const r = repair ?? createRepair()
  return render(
    <MemoryRouter>
      <RepairCard repair={r} workers={[]} />
    </MemoryRouter>
  )
}

// ---------------------------------------------------------------------------
// Tests: Basic rendering
// ---------------------------------------------------------------------------

describe('RepairCard — basic rendering', () => {
  it('renders customer name', () => {
    renderCard()
    expect(screen.getByText('Jane Doe')).toBeInTheDocument()
  })

  it('renders bicycle brand and model', () => {
    renderCard()
    expect(screen.getByText(/Trek Domane SL/)).toBeInTheDocument()
  })

  it('renders status badge with correct text', () => {
    renderCard()
    expect(screen.getByText(/in progress/i)).toBeInTheDocument()
  })

  it('renders assigned worker name when assignedTo is set and workers provided', () => {
    const repair = createRepair({ assignedTo: 'worker-01' })
    render(
      <MemoryRouter>
        <RepairCard repair={repair} workers={[{ id: 'worker-01', name: 'Bob Smith' }]} />
      </MemoryRouter>
    )
    expect(screen.getByText('Bob Smith')).toBeInTheDocument()
  })

  it('renders "Unassigned" when assignedTo is null', () => {
    renderCard()
    expect(screen.getByText('Unassigned')).toBeInTheDocument()
  })
})

// ---------------------------------------------------------------------------
// Tests: Status badge colors
// ---------------------------------------------------------------------------

describe('RepairCard — status badge colors', () => {
  it.each([
    ['intake', 'blue'],
    ['in_progress', 'yellow'],
    ['on_hold', 'orange'],
    ['verified', 'purple'],
    ['ready', 'green'],
  ] as [RepairDetailWithCustomer['status'], string][])(
    'applies %s status color for "%s"',
    (status, expectedColor) => {
      const repair = createRepair({ status })
      renderCard(repair)
      // Check that the badge element contains the expected color class
      const badge = screen.getByText(new RegExp(status.replace('_', ' '), 'i'))
      expect(badge.className).toContain(expectedColor)
    }
  )
})

// ---------------------------------------------------------------------------
// Tests: Card click navigation
// ---------------------------------------------------------------------------

describe('RepairCard — click navigation', () => {
  it('navigates to repair detail page when card body is clicked', async () => {
    render(
      <MemoryRouter initialEntries={['/repairs']}>
        <RepairCard repair={createRepair()} workers={[]} />
      </MemoryRouter>
    )
    const card = screen.getByRole('link')
    fireEvent.click(card)

    // MemoryRouter navigates by changing location — verify the link behavior
    expect(card).toHaveAttribute('tabIndex', '0')
  })
})

// ---------------------------------------------------------------------------
// Tests: Pickup day indicator
// ---------------------------------------------------------------------------

describe('RepairCard — pickup day indicator', () => {
  it('shows pickup indicator when pickupDate is set', () => {
    const repair = createRepair({ pickupDate: 1706918400000 }) // Feb 3, 2024
    render(
      <MemoryRouter>
        <RepairCard repair={repair} workers={[]} />
      </MemoryRouter>
    )
    expect(screen.getByText(/pickup/i)).toBeInTheDocument()
  })

  it('does not show pickup indicator when pickupDate is null', () => {
    renderCard(createRepair({ pickupDate: null }))
    expect(screen.queryByText(/pickup/i)).not.toBeInTheDocument()
  })
})

// ---------------------------------------------------------------------------
// Tests: customerName fallback
// ---------------------------------------------------------------------------

describe('RepairCard — customer name fallback', () => {
  it('renders "—" when customerName is null', () => {
    renderCard(createRepair({ customerName: null }))
    expect(screen.getByText('—')).toBeInTheDocument()
  })
})

