/**
 * RepairCalendarView — Week calendar UI for active repairs.
 *
 * 7-column grid (Mon–Sun) distributing repairs into day columns by date anchor.
 * Week navigation header with ← / Today / → and week label.
 */

import { useState, useEffect, useMemo } from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import type { RepairDetailWithCustomer } from '../types.js'
import { useRepairsForWeek } from '../hooks/useRepairsForWeek.js'
import { getDateAnchor } from '../utils/dateAnchor.js'
import { RepairCard } from './RepairCard.js'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface WorkerOption {
  id: string
  name: string
}

interface DayColumn {
  dayLabel: string // Mon, Tue, ... Sun
  dateStr: string  // "5 Feb" format
  epochMs: number  // start of that day (00:00:00)
  repairs: RepairDetailWithCustomer[]
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const DAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'] as const

/** Get the day-of-week index (0=Mon, 6=Sun) for a given epoch-ms */
function getDayIndex(epochMs: number): number {
  const date = new Date(epochMs)
  const dow = date.getDay() // 0=Sun, 1=Mon ...
  return dow === 0 ? 6 : dow - 1 // Convert to Mon=0 ... Sun=6
}

/** Format epoch-ms as "5 Feb" (day + short month) */
function formatDateShort(epochMs: number): string {
  const date = new Date(epochMs)
  return date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })
}

/** Format epoch-ms as "May 25 – May 31" for week label */
function formatWeekLabel(weekStart: number, _weekEnd: number): string {
  const start = new Date(weekStart)
  const end = new Date(_weekEnd)
  return `${start.toLocaleDateString('en-GB', { day: 'numeric', month: 'long' })} – ${end.toLocaleDateString('en-GB', { day: 'numeric', month: 'long' })}`
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function RepairCalendarView() {
  const { repairs, weekStart, weekEnd, isLoading, goPrev, goNext, goToday } = useRepairsForWeek()

  // Fetch workers list for worker name resolution
  const [workers, setWorkers] = useState<WorkerOption[]>([])

  useEffect(() => {
    fetch('/api/users')
      .then((r) => r.json())
      .then((data: WorkerOption[]) => setWorkers(data))
      .catch(() => setWorkers([]))
  }, [])

  // Build day columns and distribute repairs
  const dayColumns = useMemo(() => {
    const columns: DayColumn[] = []

    for (let i = 0; i < 7; i++) {
      const dayEpoch = weekStart + i * 24 * 60 * 60 * 1000
      columns.push({
        dayLabel: DAY_LABELS[i],
        dateStr: formatDateShort(dayEpoch),
        epochMs: dayEpoch,
        repairs: [],
      })
    }

    // Distribute repairs into day columns by date anchor
    for (const repair of repairs) {
      const anchor = getDateAnchor({ plannedDate: repair.plannedDate, createdAt: repair.createdAt })
      const dayIndex = getDayIndex(anchor)

      // Only place in column if it falls within the displayed week range
      if (dayIndex >= 0 && dayIndex < 7) {
        columns[dayIndex].repairs.push(repair)
      }
    }

    return columns
  }, [repairs, weekStart])

  const weekLabel = formatWeekLabel(weekStart, weekEnd)

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12" role="status">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    )
  }

  return (
    <div className="p-6">
      {/* Week Navigation Header */}
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-2xl font-bold text-foreground">Repair Calendar</h1>
        <div className="flex items-center gap-3">
          <button
            onClick={goPrev}
            aria-label="Previous week"
            className="p-2 rounded-lg border hover:bg-muted transition-colors"
          >
            <ChevronLeft size={18} />
          </button>
          <button
            onClick={goToday}
            aria-label="Today"
            className="px-3 py-1.5 text-sm font-medium rounded-lg border hover:bg-muted transition-colors"
          >
            Today
          </button>
          <button
            onClick={goNext}
            aria-label="Next week"
            className="p-2 rounded-lg border hover:bg-muted transition-colors"
          >
            <ChevronRight size={18} />
          </button>
        </div>
      </div>

      {/* Week Label */}
      <div className="mb-4 text-sm font-medium text-muted-foreground">
        {weekLabel}
      </div>

      {/* 7-Day Grid */}
      <div className="grid grid-cols-7 gap-3">
        {dayColumns.map((column) => (
          <DayColumn key={column.epochMs} column={column} workers={workers} />
        ))}
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Sub-component — Single Day Column
// ---------------------------------------------------------------------------

function DayColumn({ column, workers }: { column: DayColumn; workers: WorkerOption[] }) {
  return (
    <div className="min-h-[200px]">
      {/* Day Header */}
      <div className="mb-3 pb-2 border-b text-center">
        <div className="text-sm font-semibold text-muted-foreground">{column.dayLabel}</div>
        <div className="text-xs text-muted-foreground/70">{column.dateStr}</div>
      </div>

      {/* Repair Cards — empty columns show nothing */}
      {column.repairs.map((repair) => (
        <div key={repair.id} className="mb-2">
          <RepairCard repair={repair} workers={workers} />
        </div>
      ))}
    </div>
  )
}

